const e = $json.execution ?? {};
const w = $json.workflow ?? {};
const err = e.error ?? {};
const text = [
  '🛑 <b>Авария сценария: необработанная ошибка</b>',
  '<b>Сценарий:</b> ' + (w.name || 'unknown'),
  '<b>Упавшая нода:</b> ' + (e.lastNodeExecuted || 'unknown'),
  '<b>Сообщение:</b> ' + String(err.message || '').slice(0, 300),
  '<b>Execution ID:</b> ' + (e.id || 'n/a'),
  '<b>Режим:</b> ' + (e.mode || 'n/a'),
  '',
  'Действие дежурного: открыть execution по ID, проверить retry_payload в orders, перезапустить по TESTING_PROTOCOL.md.'
].join('\n');
return [{ json: {
  ts: new Date().toISOString(),
  workflow_name: w.name || 'unknown',
  execution_id: e.id || '',
  last_node: e.lastNodeExecuted || '',
  error_message: String(err.message || '').slice(0, 500),
  alert_text: text
} }];
